cssChange:
/* On the narrow landscape split, reclaim the unused dial slot so all seven
   plates can use the shared height rather than shrink to the card width. */
@media(max-width:600px) and (orientation:landscape) and (max-height:400px){.training-main:not(.has-spindle-sweep) .precision-readouts{grid-template-columns:minmax(0,1fr) 56px}}
